import React, { useState } from "react";
import {
  Box,
  Flex,
  SimpleGrid,
  Text,
  Input,
  InputGroup,
  InputLeftElement,
  Tooltip,
} from "@chakra-ui/react";
import { SearchIcon } from "@chakra-ui/icons";
import { Country } from "../../data";
import * as CountryFlags from "country-flag-icons/react/3x2";
import { hasFlag } from "country-flag-icons";
import { colors } from "../../theme/tokens";
import { useAnalytics } from "../../hooks/useAnalytics";

interface CountrySelectorProps {
  countries: Country[];
  selectedCountry: Country | null;
  onSelectCountry: (country: Country) => void;
}

const CountrySelector: React.FC<CountrySelectorProps> = ({
  countries,
  selectedCountry,
  onSelectCountry,
}) => {
  const { trackEvent } = useAnalytics();
  const [searchQuery, setSearchQuery] = useState<string>("");

  const filteredCountries =
    searchQuery.trim() === ""
      ? countries
      : countries.filter((country) =>
          country.countryName.toLowerCase().includes(searchQuery.toLowerCase()),
        );

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(e.target.value);
  };
  
  // Use theme tokens for consistent styling
  const { 
    cardBg, 
    hoverBg, 
    borderColor, 
    selectedBorderColor 
  } = colors;

  return (
    <Box mb={6} width="100%">
      <Box maxW="md" mx="auto" mb={6}>
        <InputGroup>
          <InputLeftElement pointerEvents="none">
            <SearchIcon color={colors.iconColor} />
          </InputLeftElement>
          <Input
            placeholder="Search countries..."
            value={searchQuery}
            onChange={handleSearch}
            borderRadius="full"
            bg={cardBg}
            _focus={{
              boxShadow: "outline",
              borderColor: "primary.500",
            }}
          />
        </InputGroup>
      </Box>

      <SimpleGrid
        columns={{ base: 2, sm: 3, md: 4, lg: 4 }}
        spacing={5}
        maxW="4xl"
        mx="auto"
      >
        {filteredCountries.map((country) => (
          <Tooltip
            key={country.id}
            label={country.countryName}
            placement="top"
            hasArrow
          >
            <Box
              onClick={() => {
                // Track country selection
                trackEvent({
                  category: 'navigation',
                  action: 'country_selected',
                  label: country.countryName
                });
                onSelectCountry(country);
              }}
              cursor="pointer"
              borderWidth="2px"
              borderRadius="lg"
              p={3}
              bg={cardBg}
              borderColor={
                selectedCountry?.id === country.id
                  ? selectedBorderColor
                  : borderColor
              }
              _hover={{ bg: hoverBg }}
              transition="all 0.2s"
              textAlign="center"
              role="group"
            >
              <Flex
                direction="column"
                align="center"
                justify="center"
                height="100%"
              >
                <Box
                  mb={2}
                  width="80px"
                  height="60px"
                  overflow="hidden"
                  borderRadius="sm"
                  filter={
                    selectedCountry?.id === country.id
                      ? "none"
                      : "grayscale(30%)"
                  }
                  transition="all 0.2s"
                  _groupHover={{ filter: "none" }}
                >
                  {hasFlag(country.countryCode.toUpperCase()) ? 
                    React.createElement(CountryFlags[country.countryCode.toUpperCase() as keyof typeof CountryFlags], {
                      title: country.countryName,
                      style: { width: '100%', height: '100%', objectFit: 'cover' }
                    }) : 
                    <Box 
                      width="100%" 
                      height="100%" 
                      bg="gray.200"
                      display="flex"
                      alignItems="center"
                      justifyContent="center"
                      fontSize="xs"
                    >
                      {country.countryCode.toUpperCase()}
                    </Box>
                  }
                </Box>
                <Text
                  fontSize="sm"
                  fontWeight={
                    selectedCountry?.id === country.id ? "bold" : "normal"
                  }
                  isTruncated
                >
                  {country.countryName}
                </Text>
              </Flex>
            </Box>
          </Tooltip>
        ))}
      </SimpleGrid>
    </Box>
  );
};

export default CountrySelector;
