import { useCallback } from 'react';

// Define event category types
export type EventCategory = 
  | 'visa_selection'
  | 'navigation'
  | 'user_interaction'
  | 'error';

// Define event action types
export type VisaSelectionAction = 
  | 'recommended_selected'
  | 'alternative_selected'
  | 'country_selected';

export type NavigationAction = 
  | 'page_view'
  | 'external_link'
  | 'internal_link';

export type UserInteractionAction =
  | 'button_click'
  | 'filter_change'
  | 'expand_details'
  | 'question_answered';

export type ErrorAction =
  | 'api_error'
  | 'loading_error'
  | 'validation_error';

// Union type for all actions
export type EventAction = 
  | VisaSelectionAction
  | NavigationAction
  | UserInteractionAction
  | ErrorAction;

// Event interface
export interface AnalyticsEvent {
  category: EventCategory;
  action: EventAction;
  label?: string;
  value?: number;
  nonInteraction?: boolean;
  transport?: 'beacon' | 'xhr' | 'image';
}

/**
 * Custom hook for tracking events with Google Analytics
 * Provides type-safe event tracking functions
 */
export const useAnalytics = (): { 
  trackEvent: (event: AnalyticsEvent) => void;
  trackPageView: (path: string, title?: string) => void;
  trackVisaSelection: (action: VisaSelectionAction, visaTitle: string, countryCode?: string) => void;
} => {
  /**
   * Track an event in Google Analytics
   */
  const trackEvent = useCallback((event: AnalyticsEvent): void => {
    if (typeof window !== 'undefined' && window.gtag) {
      window.gtag('event', event.action, {
        event_category: event.category,
        event_label: event.label,
        value: event.value,
        non_interaction: event.nonInteraction,
        transport: event.transport
      });
    }
  }, []);

  /**
   * Track a page view
   */
  const trackPageView = useCallback((path: string, title?: string): void => {
    if (typeof window !== 'undefined' && window.gtag && window.GOOGLE_ANALYTICS_ID) {
      window.gtag('config', window.GOOGLE_ANALYTICS_ID, {
        page_path: path,
        page_title: title
      });
    }
  }, []);

  /**
   * Track a visa selection
   */
  const trackVisaSelection = useCallback((
    action: VisaSelectionAction, 
    visaTitle: string, 
    countryCode?: string
  ): void => {
    trackEvent({
      category: 'visa_selection',
      action,
      label: `${visaTitle}${countryCode ? ` (${countryCode})` : ''}`
    });
  }, [trackEvent]);

  return { 
    trackEvent,
    trackPageView,
    trackVisaSelection 
  };
};
