import {
  Box,
  Button,
  Center,
  Container,
  Flex,
  Heading,
  Icon,
  Spinner,
  Text
} from "@chakra-ui/react";
import { ChevronLeft } from "lucide-react";
import React, { useEffect, useState } from "react";
import CountryFlag from "../../components/CountryFlag";
import { Country, supportedCountries } from "../../data";
import { VisaDecisionTree } from "../../data/model";
import { colors } from "../../theme/tokens";
import { CountrySelector, DecisionTreeExplorer } from "./";

interface VisaDecisionTreeContainerProps {
  title?: string;
  subtitle?: string;
}

const VisaDecisionTreeContainer: React.FC<VisaDecisionTreeContainerProps> = ({
  title = "Find Your Visa Requirements",
  subtitle = "Answer a few questions to determine which visa you need",
}) => {
  const [selectedCountry, setSelectedCountry] = useState<Country | null>(null);
  const [decisionTree, setDecisionTree] = useState<VisaDecisionTree | null>(
    null,
  );
  const [loading, setLoading] = useState<boolean>(false);

  // Flag icons are now loaded via country-flag-icons package as React components

  useEffect(() => {
    if (selectedCountry) {
      setLoading(true);

      // Small artificial delay to show loading state
      setTimeout(() => {
        setDecisionTree(selectedCountry.decisionTree);
        setLoading(false);
      }, 300);
    }
  }, [selectedCountry]);

  const handleCountrySelect = (country: Country): void => {
    setSelectedCountry(country);
    setDecisionTree(null);
  };

  const handleReset = (): void => {
    setSelectedCountry(null);
    setDecisionTree(null);
  };

  // Use theme tokens for consistent styling
  const {
    headingColor,
    bodyText: subTextColor,
    linkColor
  } = colors;

  return (
    <Box py={10} borderRadius="lg" width="100%">
      <Container maxW="4xl">
        <Box textAlign="center" mb={8}>
          {!selectedCountry ? (
            <>
              <Heading size="xl" mb={3} color={headingColor}>
                {title}
              </Heading>
              {subtitle && (
                <Text fontSize="lg" color={subTextColor}>
                  {subtitle}
                </Text>
              )}
            </>
          ) : (
            <Flex
              direction="column"
              align="center"
              justify="center"
              width="100%"
            >
              {/* Responsive header layout */}
              <Flex 
                width="100%" 
                mb={2} 
                direction={{ base: "column", md: "row" }}
                justify={{ base: "center", md: "space-between" }}
                align="center"
                gap={{ base: 4, md: 2 }}
                px={4}
                py={3}
              >
                {/* Back button */}
                <Button
                  onClick={handleReset}
                  colorScheme="primary"
                  variant="outline"
                  leftIcon={<Icon as={ChevronLeft} boxSize={4} />}
                  alignSelf={{ base: "center", md: "flex-start" }}
                  mb={{ base: 2, md: 0 }}
                  width={{ base: "full", md: "auto" }}
                >
                  Back to All Countries
                </Button>

                {/* Flag in center */}
                <Box textAlign="center" mb={{ base: 2, md: 0 }}>
                  <CountryFlag
                    countryCode={selectedCountry.countryCode.toLowerCase()}
                    countryName={selectedCountry.countryName}
                    size={100}
                  />
                </Box>

                {/* Country name */}
                <Heading 
                  size="xl" 
                  color={headingColor}
                  textAlign={{ base: "center", md: "right" }}
                >
                  {selectedCountry.countryName}
                </Heading>
              </Flex>
            </Flex>
          )}
        </Box>

        {!selectedCountry && (
          <CountrySelector
            countries={supportedCountries}
            selectedCountry={selectedCountry}
            onSelectCountry={handleCountrySelect}
          />
        )}

        {loading && (
          <Center py={10}>
            <Spinner
              size="xl"
              thickness="4px"
              speed="0.65s"
              color={linkColor}
            />
          </Center>
        )}

        {selectedCountry && decisionTree && !loading && (
          <DecisionTreeExplorer
            decisionTree={decisionTree}
            countryName={selectedCountry.countryName}
          />
        )}
      </Container>
    </Box>
  );
};

export default VisaDecisionTreeContainer;
