import React from 'react';
import { Box } from '@chakra-ui/react';
import * as CountryFlags from 'country-flag-icons/react/3x2';
import { hasFlag } from 'country-flag-icons';

interface CountryFlagProps {
  countryCode: string;
  countryName?: string;
  size?: string | number;
  grayscale?: boolean;
}

const CountryFlag: React.FC<CountryFlagProps> = ({
  countryCode,
  countryName = '',
  size = '2rem',
  grayscale = false,
}) => {
  const upperCaseCode = countryCode.toUpperCase();
  
  // Convert size to pixels if it's a number
  const sizeValue = typeof size === 'number' ? `${size}px` : size;
  
  return (
    <Box
      width={sizeValue}
      height={sizeValue}
      overflow="hidden"
      borderRadius="sm"
      filter={grayscale ? "grayscale(30%)" : "none"}
      transition="all 0.2s"
    >
      {hasFlag(upperCaseCode) ? 
        React.createElement(CountryFlags[upperCaseCode as keyof typeof CountryFlags], {
          title: countryName,
          style: { width: '100%', height: '100%', objectFit: 'cover' }
        }) : 
        <Box 
          width="100%" 
          height="100%" 
          bg="gray.200"
          display="flex"
          alignItems="center"
          justifyContent="center"
          fontSize="xs"
        >
          {upperCaseCode}
        </Box>
      }
    </Box>
  );
};

export default CountryFlag;
